// Same search order and bounds as kernel.cpp; only causal stopping is added.
#include "kernel.cpp"
extern "C" {
void* adaptive_repair_proof(void* ptr,const int64_t* warmcounts,const int* accepted,const double* inpoints,const int* instride,int inn,const double* exactpoints,const int* exactstride,int exactn,int budget,int64_t fixed_us,int64_t margin_us,int64_t* gate){try{if(budget<0||budget>100000)return nullptr;auto begin=std::chrono::steady_clock::now();gate[0]=0;gate[1]=0;gate[2]=0;int terminal_lower=500000;auto old=static_cast<TubeContext*>(static_cast<Context*>(ptr));auto c=new RepairContext(old->extent.data(),old->anchor.data(),old->road.data(),old->origin.data(),old->qx,old->qy,old->radius,old->qn,old->qd);c->epsilon=old->epsilon;c->nodes=old->nodes;c->counts.resize(c->nodes.size());c->geometries.resize(c->nodes.size());c->current.resize(c->nodes.size(),0);c->upper=c->outside_upper;
 for(size_t i=0;i<c->nodes.size();i++){Node& n=c->nodes[i];if(n.status==1)continue;if(old->nodes[i].status==2){c->current[i]=1;for(int s=0;s<2;s++){auto v=warmcounts+8*i+4*s;c->counts[i][s]={v[0],v[1],v[2],v[3]};}}n.status=accepted[i]==1?2:0;}
 if(budget>0){Rays inliers(inpoints,instride,inn,c->origin),exact(exactpoints,exactstride,exactn,c->origin);using Q=std::pair<int,int>;std::priority_queue<Q,std::vector<Q>,std::greater<Q>> queue;for(size_t i=0;i<c->nodes.size();i++)if(c->nodes[i].status==0)queue.push({c->nodes[i].lower,i});V padded=c->extent;for(double& x:padded)x+=.03;double body=norm(padded);
 while(!queue.empty()&&int(c->visited.size())<budget){auto top=queue.top();int frontier=std::min({c->outside_lower,top.first,terminal_lower});int64_t spent=fixed_us+int64_t(ceil(std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()*1e6));gate[1]=frontier;gate[2]=spent;if(frontier-spent>=margin_us){gate[0]=1;break;}if(c->upper<=spent){gate[0]=2;break;}if(top.first>=c->upper){gate[0]=3;break;}queue.pop();int i=top.second;c->visited.push_back(i);Node n=c->nodes[i];Boxes b=boxes(n,c->extent,c->anchor,c->road,c->origin);if(!c->current[i]){c->counts[i]=mixed_count(b,inliers,exact,c->epsilon);c->current[i]=2;c->bound_calls++;}auto cc=c->counts[i];if(excludes(cc[0],c->qn,c->qd)||excludes(cc[1],c->qn,c->qd)){c->nodes[i].status=2;continue;}
 if((c->visited.size()-1)%64==0){double pose[6];for(int j=0;j<6;j++)pose[j]=(n.lo[j]+n.hi[j])/2;V local{pose[0],pose[1],pose[2]};int u=point_upper(local,c->qx,c->qy,c->radius);if(u<c->upper){Boxes point{};point.center=add(c->anchor,mv(c->road,local));point.r=rot(pose[3],pose[4],pose[5]);point.inner=point.outer=padded;point.o=mv(trans(point.r),sub(c->origin,point.center));point.resolved=true;bool inside=true;for(int j=0;j<3;j++)inside&=std::abs(point.o[j])<=padded[j];point.resolved=!(inside&&c->origin[2]>=.15);auto pc=mixed_count(point,inliers,exact,0);c->witness_calls++;if(!excludes(pc[0],c->qn,c->qd)&&!excludes(pc[1],c->qn,c->qd)){c->upper=u;c->witness.assign(pose,pose+6);}}}
 int axis=0;double weight=-1;for(int j=0;j<6;j++){double h=(n.hi[j]-n.lo[j])/2;double w=j<3?h:2*body*sin(std::min(h,M_PI)/2);if(w>weight){weight=w;axis=j;}}double mid=(n.lo[axis]+n.hi[axis])/2;if(mid==n.lo[axis]||mid==n.hi[axis]){c->nodes[i].status=4;terminal_lower=std::min(terminal_lower,n.lower);continue;}Node l=n,r=n;l.hi[axis]=mid;r.lo[axis]=mid;l.parent=r.parent=i;l.left=l.right=r.left=r.right=-1;l.status=r.status=0;l.lower=lower(l,c->qx,c->qy,c->radius);r.lower=lower(r,c->qx,c->qy,c->radius);int j=c->nodes.size();c->nodes[i].status=1;c->nodes[i].left=j;c->nodes[i].right=j+1;c->nodes.push_back(l);c->nodes.push_back(r);c->counts.resize(c->nodes.size());c->geometries.resize(c->nodes.size());c->current.resize(c->nodes.size(),0);queue.push({l.lower,j});queue.push({r.lower,j+1});
 }}c->repair_seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();return static_cast<Context*>(c);}catch(...){return nullptr;}}
}
